 \label{def:expres}
We say that an $m$-ary weighted relation $\phi$ is \emph{expressible} over a valued constraint
language $\Gamma$ if there exists a VCSP instance $\ensuremath{I} \in \VCSP(\Gamma)$ 
with variables $V=\{x_1,\ldots,x_n,y_1,\ldots,y_m\}$,
such that
\begin{equation}
\phi(y_1,\ldots,y_m) = \min_{x_1\in D,\ldots,x_n\in D}\ensuremath{I}(x_1,\ldots,x_n,y_1,\ldots,y_m)\,.
\end{equation}

The \emph{superposition} of a $k$-ary operation $f:D^k\rightarrow D$ with $k$
$\ell$-ary operations $g_i:D^\ell\rightarrow D$ for $1\leq i\leq k$ is the
$\ell$-ary function $f[g_1,\ldots,g_k]:D^\ell\to D$ defined by
\begin{equation}
f[g_1,\ldots,g_k](x_1,\ldots,x_\ell)=f(g_1(x_1,\ldots,x_\ell),\ldots,g_k(x_1,\ldots,x_\ell))\,.
\end{equation}

 \label{defn:wop}

A $k$-ary \emph{weighting}
of a clone $C$ is a function $\omega : C^{(k)} \rightarrow \mathbb{Q}$ such that
$\omega(f) < 0$ only if $f$ is a projection and

\begin{equation}\label{ineq:weightingzero}
  \sum_{f \in C^{(k)}}\omega(f)\ =\ 0\,.
\end{equation}

We define $\supp(\omega)=\{f\in C^{(k)}\:|\:\omega(f)>0\}$.

 \label{defn:wp_trans}

For any clone $C$, any $k$-ary weighting $\omega$ of $C$, and any $g_1,\ldots,g_k \in
C^{(\ell)}$, the \emph{superposition}
of $\omega$
and $g_1,\ldots,g_k$, is the function $\omega[g_1,\ldots,g_k]: C^{(\ell)}
\rightarrow \mathbb{Q}$ defined by

\begin{equation}
\omega[g_1,\ldots,g_k](f') = \sum_{\{f \in C^{(k)}\:|\:f[g_1,\ldots,g_k] =
f'\}}\omega(f)\,.
\end{equation}

If $\omega$ satisfies~\eqref{ineq:weightingzero} then so does
$\omega[g_1,\ldots,g_k]$.
If the result of a superposition is a valid weighting (that is, negative weights
are only assigned to projections) then that superposition will be called a
\emph{proper} superposition.

